# -*- coding: utf-8 -*-
# Batch 4: similarity, right triangles and trig, circles, area, coordinates, transformations, constructions.
from proofs3 import P
PR4=[
P('p-aa-sim','sim','AA similarity: two equal angle pairs make triangles similar',
 '△ABC and △DEF with ∠A ≅ ∠D and ∠B ≅ ∠E.','△ABC ~ △DEF',
 [('∠A ≅ ∠D and ∠B ≅ ∠E','Given'),('m∠A + m∠B + m∠C = 180° and m∠D + m∠E + m∠F = 180°','Triangle angle sum theorem'),('m∠C = 180° − m∠A − m∠B and m∠F = 180° − m∠D − m∠E','Subtraction property of equality'),('m∠C = m∠F','Substitution (equal angles)'),('All three angle pairs are congruent, so △ABC ~ △DEF','Definition of similar triangles (angles equal; sides then proportional)')],
 'Two angle pairs force the third pair. Equal angles in all three places means the same shape.',
 'AA is the most-used similarity test. It is why a flat shadow can measure a tall tree.',
 'AA needs two pairs only. A single angle pair says nothing without more data.',13),
P('p-tpt','sim','A line parallel to one side of a triangle divides the other two sides proportionally',
 '△ABC with DE ∥ BC, D on AB and E on AC.','AD/DB = AE/EC',
 [('DE ∥ BC','Given'),('∠ADE ≅ ∠B and ∠AED ≅ ∠C','Corresponding angles postulate'),('△ADE ~ △ABC','AA similarity'),('AD/AB = AE/AC','Corresponding sides of similar triangles are proportional'),('AD·AC = AE·AB','Cross-multiplication'),('(AD)(AE + EC) = (AE)(AD + DB)','Segment addition (AC = AE + EC and AB = AD + DB)'),('AD·EC = AE·DB, so AD/DB = AE/EC','Subtraction (AD·AE cancels) and division property')],
 'Prove the small and big triangles similar, then rearrange the proportion.',
 'The converse is also true: if the sides are cut proportionally, the line is parallel to the third side.',
 'The proportion compares part to part (AD/DB), not part to whole (AD/AB).',17),
P('p-sim-peri','sim','Similar figures: perimeters are in the same ratio as sides',
 '△ABC ~ △DEF with scale factor k: AB = k·DE, BC = k·EF, CA = k·FD.','Perimeter(△ABC) = k·Perimeter(△DEF)',
 [('AB = k·DE, BC = k·EF, CA = k·FD','Given (definition of similar triangles)'),('Perimeter(ABC) = AB + BC + CA','Definition of perimeter'),('Perimeter(ABC) = k·DE + k·EF + k·FD','Substitution'),('Perimeter(ABC) = k(DE + EF + FD)','Distributive property'),('Perimeter(ABC) = k·Perimeter(DEF)','Definition of perimeter')],
 'Factor the scale factor out of the sum of the three sides.',
 'Lengths scale by k. Areas scale by k². Volumes scale by k³. Perimeter is a length, so it scales by k.',
 'Do not square k for perimeter. That is for area.',11),
P('p-sim-area','sim','Similar triangles: areas are in the ratio k²',
 '△ABC ~ △DEF with scale factor k. Heights from A and D to BC and EF satisfy h₁ = k·h₂.','Area(ABC) = k²·Area(DEF)',
 [('BC = k·EF and h₁ = k·h₂','Given (similar triangles; corresponding altitudes scale by k)'),('Area(ABC) = ½·BC·h₁','Area formula for triangles'),('Area(ABC) = ½·(k·EF)(k·h₂)','Substitution'),('Area(ABC) = k²·(½·EF·h₂)','Commutative and associative properties'),('Area(ABC) = k²·Area(DEF)','Area formula for triangles')],
 'Both the base and the height are scaled by k, so k appears twice.',
 'The same logic makes the ratio of volumes k³ because three dimensions are scaled.',
 'The area ratio is k², not k. A 2× longer triangle has 4× the area.',13),
P('p-alt-sim','sim','The altitude to the hypotenuse creates two similar triangles',
 'Right △ABC with right angle at C. CD ⟂ AB, D on AB.','△ACD ~ △ABC ~ △CBD',
 [('∠ADC and ∠ACB are right angles','Definition of perpendicular; given'),('∠A ≅ ∠A','Reflexive property'),('△ACD ~ △ABC','AA similarity'),('∠BDC and ∠ACB are right angles and ∠B ≅ ∠B','Definition of perpendicular; reflexive property'),('△CBD ~ △ABC','AA similarity'),('△ACD ~ △ABC ~ △CBD','Transitive property of similarity')],
 'Each small triangle shares one angle with the big one and has a right angle.',
 'From these, AC² = AD·AB and BC² = BD·AB. Adding gives the Pythagorean theorem.',
 'Match the vertices in the correct order. △ACD ~ △ABC pairs A with A, C with B and D with C.',15),
P('p-leg-geo','sim','Each leg is the geometric mean of the hypotenuse and the adjacent segment',
 'Right △ABC with right angle at C. CD ⟂ AB, D on AB. AB = c, AD = m.','AC² = m·c',
 [('△ACD ~ △ABC','AA similarity (shared ∠A and right angles)'),('AD/AC = AC/AB','Corresponding sides of similar triangles are proportional'),('m/AC = AC/c','Substitution'),('AC² = m·c','Cross-multiplication')],
 'Use similar triangles so that AC appears in the numerator of one ratio and the denominator of another.',
 'The geometric mean pattern: the leg is the middle term of the proportion m : AC = AC : c.',
 'Be careful which segment is adjacent. AC borders AD, not DB.',14),
P('p-30-60','rt','The 30-60-90 triangle has sides in the ratio 1 : √3 : 2',
 'Equilateral △ABC with side 2. D is the midpoint of BC; AD is drawn.','AD = √3',
 [('AB = AC = 2, BD = DC = 1','Given; definition of midpoint'),('AD ⟂ BC','The median to the base of an isosceles triangle is also the altitude'),('△ABD is a right triangle with hypotenuse 2 and leg 1','Definition of right triangle'),('AD² + 1² = 2²','Pythagorean theorem'),('AD² = 3, so AD = √3','Subtraction and square root (length is positive)')],
 'Cut the equilateral triangle in half and use the Pythagorean theorem on the half.',
 'The half-triangle has angles 30°, 60° and 90° with sides 1, √3 and 2.',
 'Side 1 is opposite 30°, √3 is opposite 60°. Do not swap them.',12),
P('p-45-45','rt','The 45-45-90 triangle has sides in the ratio 1 : 1 : √2',
 'Right △ABC with right angle at C and AC = BC = 1.','AB = √2',
 [('AC = BC = 1','Given'),('AC² + BC² = AB²','Pythagorean theorem'),('1 + 1 = AB²','Substitution'),('AB² = 2','Addition'),('AB = √2','Square root property (length is positive)')],
 'Two equal legs and a right angle: just use a² + b² = c².',
 'This triangle is half of a square. Its diagonal is √2 times its side.',
 'The hypotenuse is the larger side, √2 ≈ 1.41, not 2.',11),
P('p-sin-cos','rt','sin A = cos(90° − A)',
 'Right △ABC with right angle at C.','sin A = cos B',
 [('m∠A + m∠B = 90°','Triangle angle sum (right triangle)'),('sin A = BC/AB','Definition of sine'),('cos B = BC/AB','Definition of cosine (BC is adjacent to B)'),('sin A = cos B','Substitution'),('sin A = cos(90° − A)','Substitution (m∠B = 90° − m∠A)')],
 'The side opposite A is the side adjacent to B. Same side, same hypotenuse.',
 'The word “cosine” means “complement’s sine”. This is where the name comes from.',
 'Adjacent and opposite swap when you change the reference angle.',13),
P('p-pyth-id','rt','sin²A + cos²A = 1',
 'Right △ABC with right angle at C. Let a = BC, b = AC, c = AB.','sin²A + cos²A = 1',
 [('sin A = a/c and cos A = b/c','Definitions of sine and cosine'),('sin²A + cos²A = a²/c² + b²/c²','Substitution'),('sin²A + cos²A = (a² + b²)/c²','Adding fractions with a common denominator'),('a² + b² = c²','Pythagorean theorem'),('sin²A + cos²A = c²/c² = 1','Substitution and simplification')],
 'Write both ratios using the triangle’s sides, then use a² + b² = c².',
 'This identity is the Pythagorean theorem in disguise. It lets you find cos A from sin A.',
 'sin²A means (sin A)², not sin(A²).',15),
P('p-area-sin','rt','Triangle area = ½·a·b·sin C',
 '△ABC with sides a = BC and b = CA and angle C. Let h be the altitude from A to line BC.','Area = ½·a·b·sin C',
 [('Area = ½·a·h','Area formula for triangles'),('sin C = h/b','Definition of sine in the right triangle formed by the altitude'),('h = b·sin C','Multiplication property of equality'),('Area = ½·a·b·sin C','Substitution')],
 'Express the height using sine so that base and height become two sides and the angle between them.',
 'If C = 90°, sin C = 1 and the formula becomes ½ab, the usual right-triangle area.',
 'The angle must be the one BETWEEN the two sides you multiply.',16),
P('p-dist','crd','The distance formula comes from the Pythagorean theorem',
 'Points P(x₁, y₁) and Q(x₂, y₂). Draw a right triangle with legs parallel to the axes and hypotenuse PQ.','PQ = √((x₂ − x₁)² + (y₂ − y₁)²)',
 [('Horizontal leg = |x₂ − x₁| and vertical leg = |y₂ − y₁|','Distance on a number line'),('PQ² = |x₂ − x₁|² + |y₂ − y₁|²','Pythagorean theorem'),('PQ² = (x₂ − x₁)² + (y₂ − y₁)²','Squaring removes the absolute value signs'),('PQ = √((x₂ − x₁)² + (y₂ − y₁)²)','Square root property (distance is positive)')],
 'Build a right triangle from the two points and apply a² + b² = c².',
 'Because squares are never negative, the order of the points does not matter.',
 'Subtract the coordinates in the same order for x and y, but note the order never changes the result after squaring.',12),
P('p-slope-perp','crd','Perpendicular lines have slopes whose product is −1',
 'Line ℓ through O(0, 0) and A(1, m), and line k through O and B(−m, 1), where m ≠ 0.','ℓ ⟂ k',
 [('slope of ℓ = m/1 = m and slope of k = 1/(−m) = −1/m','Slope formula'),('OA² = 1 + m² and OB² = m² + 1','Distance formula'),('AB² = (1 + m)² + (m − 1)² = 2m² + 2','Distance formula, then algebra'),('OA² + OB² = 2m² + 2 = AB²','Addition (substitution)'),('∠AOB is a right angle, so ℓ ⟂ k','Converse of the Pythagorean theorem'),('m · (−1/m) = −1','Multiplication')],
 'Test a pair of lines with slopes m and −1/m by checking the Pythagorean converse in a triangle.',
 'Any line can be moved so it passes through the origin without changing its slope, so the same argument covers every pair. This is why “flip and change the sign” gives a perpendicular slope.',
 'Horizontal and vertical lines are perpendicular too but their slopes are 0 and undefined, so this product rule does not apply.',17),
P('p-circle-eq','crd','The equation of a circle',
 'A circle has center (h, k) and radius r. P(x, y) is any point on it.','(x − h)² + (y − k)² = r²',
 [('P is on the circle if and only if its distance from (h, k) is r','Definition of a circle'),('√((x − h)² + (y − k)²) = r','Distance formula'),('(x − h)² + (y − k)² = r²','Squaring both sides (both are positive)')],
 'A circle is the set of points at distance r from the center. Write that using the distance formula.',
 'The Pythagorean theorem hides inside the circle’s equation.',
 'The center is (h, k), so the equation contains x − h, not x + h.',11),
P('p-mid-coord','crd','Coordinate proof: the midsegment of a triangle is parallel to the base',
 'Triangle with A(0, 0), B(2a, 0), C(2b, 2c). M is the midpoint of AC and N is the midpoint of BC.','MN ∥ AB and MN = ½·AB',
 [('M = (b, c) and N = (a + b, c)','Midpoint formula'),('slope of MN = (c − c)/((a + b) − b) = 0','Slope formula'),('slope of AB = 0','Slope formula (AB is on the x-axis)'),('MN ∥ AB','Lines with equal slopes are parallel'),('MN = |a| and AB = 2|a|, so MN = ½·AB','Distance formula')],
 'Pick coordinates that use doubled values (2a, 2b, 2c) so the midpoints have no fractions.',
 'Placing one side on the x-axis and using even coordinates is the standard trick. The result holds for every triangle because a, b, c are general.',
 'Do not use specific numbers. A single example does not prove the theorem.',16),
P('p-rect-coord','crd','Coordinate proof: the diagonals of a rectangle are equal',
 'Rectangle with A(0, 0), B(w, 0), C(w, h), D(0, h).','AC = BD',
 [('AC = √((w − 0)² + (h − 0)²) = √(w² + h²)','Distance formula'),('BD = √((0 − w)² + (h − 0)²) = √(w² + h²)','Distance formula'),('AC = BD','Substitution (both equal √(w² + h²))')],
 'Place the rectangle on the axes so the distances are easy.',
 'This is the coordinate version of the proof that the diagonals of a rectangle are congruent. The letters w and h stand for any width and height.',
 'Use variables, not numbers, so the proof covers ALL rectangles.',12),
P('p-mid-diag-coord','crd','Coordinate proof: the diagonals of a parallelogram bisect each other',
 'Parallelogram with A(0, 0), B(a, 0), D(b, c), C(a + b, c).','The midpoint of AC equals the midpoint of BD',
 [('Midpoint of AC = ((a + b)/2, c/2)','Midpoint formula'),('Midpoint of BD = ((a + b)/2, c/2)','Midpoint formula'),('The midpoints are the same point','Substitution'),('The diagonals bisect each other','Definition of bisect')],
 'Name the vertices with letters that make the parallelogram general, then compute both midpoints.',
 'The vertex C = (a + b, c) comes from adding the vectors AB and AD.',
 'A parallelogram placed on the axes needs the fourth vertex (a + b, c), not (a, c).',14),
P('p-refl-dist','trn','A reflection preserves distance',
 'Points P and Q with images P′ and Q′ under reflection in the line ℓ. Let R be the foot of the perpendicular from P to ℓ and S the foot from Q.','P′Q′ = PQ',
 [('PR = P′R and QS = Q′S, with right angles at R and S','Definition of reflection'),('Coordinates: put ℓ on the x-axis, P(x₁, y₁), Q(x₂, y₂)','Choice of coordinates'),('P′ = (x₁, −y₁) and Q′ = (x₂, −y₂)','Definition of reflection in the x-axis'),('P′Q′ = √((x₂ − x₁)² + (−y₂ + y₁)²)','Distance formula'),('P′Q′ = √((x₂ − x₁)² + (y₂ − y₁)²) = PQ','Squares ignore sign')],
 'Put the mirror on the x-axis, then compare the two distances.',
 'Distance is preserved, so reflections are called isometries. Angles and shapes are preserved too.',
 'Reflection reverses orientation but not size. Clockwise becomes counter-clockwise.',16),
P('p-two-refl','trn','Two reflections in parallel lines make a translation',
 'Lines ℓ and m are parallel and d apart. A point P is reflected in ℓ to P′, then in m to P″.','PP″ = 2d, perpendicular to the lines',
 [('Put ℓ at x = 0 and m at x = d, with P = (p, y)','Choice of coordinates'),('P′ = (−p, y)','Reflection in x = 0'),('P″ = (2d − (−p), y) = (2d + p, y)','Reflection in x = d (x ↦ 2d − x)'),('P″ − P = (2d, 0)','Subtraction'),('Every point moves 2d in the same direction, so the composition is a translation','Definition of translation')],
 'Track one general point through both reflections.',
 'The two mirrors act like a conveyor: the shift is twice the gap between them, and the order matters.',
 'The shift is 2d, not d.',16),
P('p-two-refl-rot','trn','Two reflections in intersecting lines make a rotation',
 'Lines ℓ and m meet at O at an angle θ. A point P is reflected in ℓ, then m.','The composition is a rotation about O of 2θ',
 [('Let P have angle α from ℓ at distance r from O','Polar coordinates'),('Reflect in ℓ: angle −α, distance r','Reflection preserves distance from O'),('The line m is at angle θ, so reflection in m sends angle −α to 2θ − (−α) = 2θ + α','Reflection in a line at angle θ sends angle β to 2θ − β'),('The new point is at angle α + 2θ and distance r','Substitution'),('Every point turns 2θ about O','Definition of rotation')],
 'Use polar angles: each mirror reverses the angle measured from its line.',
 'Rotation by 2θ is why the angle between a pair of mirrors determines how many reflected images you see.',
 'The rotation is twice the angle between the lines, not the angle itself.',18),
P('p-con-pbis','con','The perpendicular bisector construction works',
 'Arcs of equal radius r > ½AB are drawn from A and from B, meeting at P and Q.','Line PQ is the perpendicular bisector of AB',
 [('AP = BP = AQ = BQ = r','Same compass setting'),('P and Q are each equidistant from A and B','Definition of equidistant'),('P and Q both lie on the perpendicular bisector of AB','Converse of the perpendicular bisector theorem'),('Two points determine one line, so line PQ is the perpendicular bisector','Two points determine a line')],
 'Show that both P and Q are equidistant from A and B. That is the same as lying on the bisector.',
 'You need r > ½AB or the arcs would not cross.',
 'Using different radii from A and from B would break the proof.',14),
P('p-con-angbis','con','The angle bisector construction works',
 'An arc from vertex B meets the sides at P and Q (BP = BQ). Equal arcs from P and Q meet at R.','Ray BR bisects ∠PBQ',
 [('BP = BQ','Same compass setting from B'),('PR = QR','Same compass setting from P and Q'),('BR = BR','Reflexive property'),('△BPR ≅ △BQR','SSS'),('∠PBR ≅ ∠QBR','CPCTC'),('Ray BR bisects ∠PBQ','Definition of angle bisector')],
 'The compass settings give three equal pairs of sides, so use SSS.',
 'Compass-and-straightedge constructions are justified by congruent triangles.',
 'The arcs from P and Q must use the same radius.',13),
P('p-con-equi','con','The equilateral triangle construction works',
 'Circles centered at A and B each with radius AB meet at C.','△ABC is equilateral',
 [('AC = AB','Radius of the circle centered at A'),('BC = AB','Radius of the circle centered at B'),('AC = BC = AB','Transitive property of equality'),('△ABC is equilateral','Definition of equilateral triangle')],
 'Both circles have the same radius, which is the segment AB itself.',
 'Euclid’s first proposition. Everything else in Book I builds on this construction.',
 'The two circles must have the SAME radius (equal to AB).',11),
P('p-con-copy','con','Copying an angle works',
 'An arc of radius r from vertex B meets the sides at P, Q. The same arc from A on a new ray meets it at P′. An arc of radius PQ from P′ meets the first arc at Q′.','∠Q′AP′ ≅ ∠QBP',
 [('BP = BQ = AP′ = AQ′ = r','Same compass setting'),('PQ = P′Q′','Same compass setting (radius PQ)'),('△BPQ ≅ △AP′Q′','SSS'),('∠QBP ≅ ∠Q′AP′','CPCTC')],
 'Copy three side lengths exactly, then triangles with the same sides have the same angles.',
 'The compass acts like a ruler that remembers a length.',
 'Q′ must be found with radius PQ, not radius r.',13),
P('p-chord-arc','cir','Equal chords have equal central angles',
 'In circle O, chords AB = CD.','∠AOB ≅ ∠COD',
 [('OA = OB = OC = OD','Radii of the same circle are equal'),('AB = CD','Given'),('△AOB ≅ △COD','SSS'),('∠AOB ≅ ∠COD','CPCTC')],
 'Radii give two equal sides in each triangle, and the chords give the third.',
 'Equal central angles also give equal arcs, so equal chords cut off equal arcs.',
 'Both chords must be in the same circle (or congruent circles).',12),
P('p-inter-chord','cir','Intersecting chords: AE · EB = CE · ED',
 'Chords AB and CD meet at E inside the circle.','AE·EB = CE·ED',
 [('Draw AC and BD','Two points determine a line'),('∠CAE ≅ ∠DBE','Inscribed angles on the same arc CD are congruent'),('∠AEC ≅ ∠BED','Vertical angles are congruent'),('△AEC ~ △DEB','AA similarity'),('AE/DE = CE/BE','Corresponding sides of similar triangles are proportional'),('AE·EB = CE·ED','Cross-multiplication')],
 'Draw two extra chords to make triangles that look different but have equal angles.',
 'The product of the two pieces is the same for every chord through E.',
 'Match sides correctly: AE with DE, CE with BE.',17),
P('p-tan-chord','cir','The tangent-chord angle equals the inscribed angle',
 'Tangent at A, chord AB, and C on the major arc. Let AD be the diameter through A.','The tangent–chord angle at A equals ∠ACB',
 [('The tangent at A is perpendicular to the diameter AD','Tangent is perpendicular to the radius'),('∠ABD = 90°','Angle in a semicircle is a right angle'),('The tangent–chord angle = 90° − ∠BAD','Complement of ∠BAD along the tangent'),('∠ADB = 90° − ∠BAD','Triangle angle sum in △ABD'),('∠ADB = ∠ACB','Inscribed angles on the same arc AB'),('The tangent–chord angle = ∠ACB','Substitution')],
 'Introduce the diameter from A, so right angles appear.',
 'This lets you find angles in circles with tangents using only inscribed angles.',
 'Use the angle on the side of the chord that is opposite the tangent angle.',18),
P('p-central-inscr','cir','An inscribed angle is half the central angle on the same arc',
 'Circle O with chord BC and A on the circle so that O lies inside ∠BAC. Ray AO meets the circle again at X.','m∠BAC = ½·m∠BOC',
 [('OA = OB = OC','Radii of the same circle'),('∠OAB ≅ ∠OBA and ∠OAC ≅ ∠OCA','Isosceles triangle theorem'),('m∠BOX = 2·m∠OAB and m∠COX = 2·m∠OAC','Exterior angle theorem (sum of remote angles)'),('m∠BOC = 2(m∠OAB + m∠OAC)','Addition property of equality'),('m∠BAC = ½·m∠BOC','Angle addition postulate and division property')],
 'Draw AO extended to X. Two isosceles triangles give two exterior angles that add up.',
 'This is the central-angle theorem, the basis of every inscribed angle fact. The case with O outside ∠BAC is handled by subtraction.',
 'This proof covers the case where O is inside the angle. Other positions need their own argument.',19),
P('p-area-tri','area','The area of a triangle is ½bh',
 '△ABC with base b and height h. Complete the parallelogram ABDC with a copy of the triangle.','Area(△ABC) = ½·b·h',
 [('Two copies of △ABC fit together to form a parallelogram with base b and height h','Rotation by 180° about the midpoint of the side'),('Area(parallelogram) = b·h','Area formula for parallelograms'),('2·Area(△ABC) = b·h','Congruent triangles have equal area'),('Area(△ABC) = ½·b·h','Division property of equality')],
 'A triangle is half a parallelogram.',
 'The height is measured at right angles to the base, even when it falls outside the triangle.',
 'Using a slanted side as the height gives a wrong area.',12),
P('p-area-trap','area','The area of a trapezoid is ½(b₁ + b₂)h',
 'Trapezoid with parallel sides b₁ and b₂ and height h. A diagonal splits it into two triangles.','Area = ½(b₁ + b₂)h',
 [('The diagonal splits the trapezoid into two triangles with bases b₁ and b₂','Definition of diagonal'),('Both triangles have height h','Parallel lines are everywhere the same distance apart'),('Area = ½·b₁·h + ½·b₂·h','Area formula for triangles and area addition'),('Area = ½(b₁ + b₂)h','Distributive property')],
 'Cut the trapezoid into two triangles that share the same height.',
 'Average the parallel sides and multiply by the height. If b₂ = 0, you get a triangle.',
 'Use the perpendicular distance between the bases, not the slanted leg.',13),
P('p-area-rhomb','area','The area of a rhombus (or kite) is ½·d₁·d₂',
 'Rhombus ABCD with diagonals AC = d₁ and BD = d₂ meeting at E.','Area = ½·d₁·d₂',
 [('AC ⟂ BD','Diagonals of a rhombus are perpendicular'),('AE = ½d₁ and BE = DE = ½d₂','Diagonals of a parallelogram bisect each other'),('Area(△ABD) = ½·BD·AE = ½·d₂·(½d₁)','Area formula (AE ⟂ BD)'),('Area(△CBD) = ½·d₂·(½d₁)','Same reasoning'),('Area = ¼·d₁d₂ + ¼·d₁d₂ = ½·d₁·d₂','Area addition postulate')],
 'The diagonal BD splits the rhombus into two triangles with height ½d₁.',
 'Kites use the same formula because their diagonals are perpendicular.',
 'The diagonals are perpendicular. That is what makes the heights easy.',14),
P('p-sector','area','The area of a sector is (θ/360)πr²',
 'A circle of radius r and a sector with central angle θ°.','Sector area = (θ/360)·π·r²',
 [('The circle’s area is πr²','Area of a circle'),('A full turn is 360°, so the sector is θ/360 of the circle','Definition of a fraction of a circle'),('Sector area = (θ/360)·πr²','Multiplication property of equality')],
 'The sector is the same fraction of the area as its angle is of a full turn.',
 'The same fraction gives the arc length: (θ/360)·2πr.',
 'Use πr² for area but 2πr for the arc.',11),
]
